#!/usr/bin/env node

/**
 * Reconstruct and verify the horizontal building seam ledger for the
 * source-locked EPSG:26910 production tile set.
 *
 * The production GLBs intentionally retain only chunk-level source OSM way
 * IDs.  This preview-only verifier joins those IDs back to the byte-locked
 * OSM PBF, projects the original closed building rings with the production
 * CRS operation, applies the production tile clipper, and records the exact
 * metre boundary intervals generated by each source way.  Adjacent intervals
 * are compared after the same six-decimal metre quantization used by the
 * production builder.  It is therefore a source/geometry evidence artifact,
 * not a runtime input or a promotion authorization.
 *
 * Usage:
 *   node scripts/world-tiles/verify-sf-building-seam-edge-ledger-v1.mjs --write
 *   node scripts/world-tiles/verify-sf-building-seam-edge-ledger-v1.mjs
 */

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync, gzipSync } from 'node:zlib';
import { loadSfMetricSharedInputs } from './build-ferry-production-tile-v1.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const MANIFEST_PATH = path.join(ROOT, 'public/data/world/production-artifacts/sf-metric-tiles-v1/sf-metric-tiles-v1.manifest.json');
const LEDGER_PATH = path.join(ROOT, 'public/data/world/preview-artifacts/sf-building-seam-edge-ledger-v1/sf-building-seam-edge-ledger-v1.ledger.json.gz');
const RECEIPT_PATH = path.join(ROOT, 'public/data/world/preview-artifacts/sf-building-seam-edge-ledger-v1/sf-building-seam-edge-ledger-v1.receipt.json');
const FERRY_TILE_ID = 'epsg26910-1441-10893';
const TILE_SIZE_METRES = 384;
const QUANTIZATION_DECIMALS = 6;
const SIDES = Object.freeze(['west', 'north', 'east', 'south']);
const SIDE_ORDER = new Map(SIDES.map((side, index) => [side, index]));

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
const q = (value) => Math.round(value * 1e6) / 1e6;
const jsonBytes = (value) => Buffer.from(`${JSON.stringify(canonical(value), null, 2)}\n`);
const relative = (filePath) => path.relative(ROOT, filePath).split(path.sep).join('/');

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map((key) => [key, canonical(value[key])]));
  return value;
}

function assertSha256(value, label) {
  assert.match(value ?? '', /^sha256:[a-f0-9]{64}$/i, `${label} must be a sha256 digest`);
}

function parseGlbJson(bytes, label) {
  assert.equal(bytes.readUInt32LE(0), 0x46546c67, `${label} GLB magic drifted`);
  assert.equal(bytes.readUInt32LE(4), 2, `${label} GLB version drifted`);
  assert.equal(bytes.readUInt32LE(8), bytes.length, `${label} GLB byte length drifted`);
  const jsonLength = bytes.readUInt32LE(12);
  assert.equal(bytes.readUInt32LE(16), 0x4e4f534a, `${label} GLB JSON chunk drifted`);
  return JSON.parse(bytes.subarray(20, 20 + jsonLength).toString('utf8').trim());
}

function tileIdentity(descriptor) {
  assert.match(descriptor.id, /^epsg26910-\d+-\d+$/, `${descriptor.id} is not an EPSG tile id`);
  assert(Array.isArray(descriptor.gridIndex) && descriptor.gridIndex.length === 2, `${descriptor.id} grid index missing`);
  const [gridEasting, gridNorthing] = descriptor.gridIndex;
  assert(Number.isInteger(gridEasting) && Number.isInteger(gridNorthing), `${descriptor.id} grid index is not integral`);
  assert.deepEqual(descriptor.originEpsg26910VerticalMetres, [gridEasting * TILE_SIZE_METRES, gridNorthing * TILE_SIZE_METRES, 0], `${descriptor.id} origin drifted`);
  return Object.freeze({
    id: descriptor.id,
    gridEasting,
    gridNorthing,
    minE: gridEasting * TILE_SIZE_METRES,
    minN: gridNorthing * TILE_SIZE_METRES,
    maxE: (gridEasting + 1) * TILE_SIZE_METRES,
    maxN: (gridNorthing + 1) * TILE_SIZE_METRES,
  });
}

function sideForPoint([e, n], tile) {
  if (e === tile.minE) return 'west';
  if (n === tile.maxN) return 'north';
  if (e === tile.maxE) return 'east';
  if (n === tile.minN) return 'south';
  return null;
}

function sideParameter(side, [e, n]) {
  if (side === 'west' || side === 'east') return q(n);
  return q(e);
}

function sideWorldRange(side, a, b) {
  return [sideParameter(side, a), sideParameter(side, b)].sort((left, right) => left - right).map(q);
}

function pointInRing([e, n], ring) {
  let inside = false;
  for (let index = 0; index < ring.length; index += 1) {
    const a = ring[index];
    const b = ring[(index + 1) % ring.length];
    if ((a[1] > n) !== (b[1] > n)) {
      const crossingE = (b[0] - a[0]) * (n - a[1]) / (b[1] - a[1]) + a[0];
      if (e < crossingE) inside = !inside;
    }
  }
  return inside;
}

/**
 * Return the source polygon's exact interior intervals on one tile side.
 * Sampling one quantized micrometre inside the tile avoids the undefined
 * point-on-boundary case and handles concave OSM rings without relying on a
 * single-ring clipped output.  These are exactly the edges contributed by
 * the source polygon after clipping to this tile.
 */
function sourceBoundaryIntervals(ring, tile, side) {
  const isVertical = side === 'west' || side === 'east';
  const boundary = side === 'west' ? tile.minE : side === 'east' ? tile.maxE : side === 'south' ? tile.minN : tile.maxN;
  const lower = isVertical ? tile.minN : tile.minE;
  const upper = isVertical ? tile.maxN : tile.maxE;
  const coordinates = [lower, upper];
  const add = (value) => { if (value >= lower - 1e-7 && value <= upper + 1e-7) coordinates.push(Math.max(lower, Math.min(upper, value))); };
  for (let index = 0; index < ring.length; index += 1) {
    const a = ring[index]; const b = ring[(index + 1) % ring.length];
    const aBoundary = isVertical ? a[0] : a[1];
    const bBoundary = isVertical ? b[0] : b[1];
    const aAlong = isVertical ? a[1] : a[0];
    const bAlong = isVertical ? b[1] : b[0];
    if (aBoundary === boundary && bBoundary === boundary) {
      add(aAlong); add(bAlong); continue;
    }
    const denominator = bBoundary - aBoundary;
    if (denominator === 0) continue;
    const t = (boundary - aBoundary) / denominator;
    if (t < -1e-7 || t > 1 + 1e-7) continue;
    add(aAlong + t * (bAlong - aAlong));
  }
  const sorted = [...new Set(coordinates.map(q))].sort((a, b) => a - b);
  const intervals = [];
  // Keep this probe below the q6 output precision: production preserves
  // sub-millimetre clipped slivers rather than dropping them by an arbitrary
  // visual epsilon (one such 30 µm sliver is source way 274615303).
  const inward = 1e-8;
  for (let index = 0; index < sorted.length - 1; index += 1) {
    const start = sorted[index]; const end = sorted[index + 1];
    if (!(end > start)) continue;
    const middle = (start + end) / 2;
    const sample = isVertical
      ? [side === 'west' ? tile.minE + inward : tile.maxE - inward, middle]
      : [middle, side === 'south' ? tile.minN + inward : tile.maxN - inward];
    if (!pointInRing(sample, ring)) continue;
    intervals.push([q(start), q(end)]);
  }
  return intervals;
}

function clipPolygon(points, tile) {
  let output = points.slice();
  const edges = [
    ([e]) => e >= tile.minE,
    ([e]) => e <= tile.maxE,
    (([, n]) => n >= tile.minN),
    (([, n]) => n <= tile.maxN),
  ];
  const intersect = (a, b, edge) => {
    if (edge === 0 || edge === 1) {
      const e = edge === 0 ? tile.minE : tile.maxE;
      const denominator = b[0] - a[0];
      assert.notEqual(denominator, 0, `${tile.id} building clip has a degenerate vertical intersection`);
      const t = (e - a[0]) / denominator;
      return [e, a[1] + t * (b[1] - a[1])];
    }
    const n = edge === 2 ? tile.minN : tile.maxN;
    const denominator = b[1] - a[1];
    assert.notEqual(denominator, 0, `${tile.id} building clip has a degenerate horizontal intersection`);
    const t = (n - a[1]) / denominator;
    return [a[0] + t * (b[0] - a[0]), n];
  };
  for (let edge = 0; edge < 4; edge += 1) {
    const input = output;
    output = [];
    if (!input.length) break;
    let a = input.at(-1);
    for (const b of input) {
      if (edges[edge](b)) {
        if (!edges[edge](a)) output.push(intersect(a, b, edge));
        output.push(b);
      } else if (edges[edge](a)) output.push(intersect(a, b, edge));
      a = b;
    }
  }
  return output;
}

function dedupeRing(points) {
  const output = [];
  for (const point of points) {
    const rounded = [q(point[0]), q(point[1])];
    if (!output.length || output.at(-1)[0] !== rounded[0] || output.at(-1)[1] !== rounded[1]) output.push(rounded);
  }
  if (output.length > 1 && output[0][0] === output.at(-1)[0] && output[0][1] === output.at(-1)[1]) output.pop();
  return output;
}

function sourceGeometryHash(feature) {
  return `sha256:${sha256(Buffer.from(JSON.stringify({
    type: 'way',
    id: feature.id,
    tags: feature.tags,
    nodeIds: feature.refs,
    coordinatesLonLat: feature.lonLat.map(([lon, lat]) => [q(lon), q(lat)]),
  })))}`;
}

function buildingBoundaryEntries(feature, tile) {
  assert(feature.tags?.building, `Way ${feature.id} is not a building`);
  assert(feature.refs[0] === feature.refs.at(-1), `Building way ${feature.id} is not closed in the source PBF`);
  const ring = feature.en.slice(0, -1);
  const clipped = dedupeRing(clipPolygon(ring, tile));
  if (clipped.length < 3) return [];
  const geometryHash = sourceGeometryHash(feature);
  const entries = [];
  for (const side of SIDES) for (const worldRangeMetres of sourceBoundaryIntervals(ring, tile, side)) {
    const isVertical = side === 'west' || side === 'east';
    const worldEndpoints = isVertical
      ? [[side === 'west' ? tile.minE : tile.maxE, worldRangeMetres[0]], [side === 'west' ? tile.minE : tile.maxE, worldRangeMetres[1]]]
      : [[worldRangeMetres[0], side === 'south' ? tile.minN : tile.maxN], [worldRangeMetres[1], side === 'south' ? tile.minN : tile.maxN]];
    const localEndpoints = worldEndpoints.map(([e, n]) => [q(e - tile.minE), q(n - tile.minN)]);
    const localRangeMetres = worldRangeMetres.map((value) => q(value - (isVertical ? tile.minN : tile.minE)));
    assert(localRangeMetres[1] > localRangeMetres[0], `${tile.id} way ${feature.id} produced a zero-length ${side} seam interval`);
    entries.push({
      sourceOsmWayId: feature.id,
      sourceFeatureId: `way/${feature.id}`,
      sourceGeometryHash: geometryHash,
      side,
      worldEndpointsEpsg26910Metres: worldEndpoints.map(([e, n]) => [q(e), q(n)]),
      localEndpointsMetres: localEndpoints,
      worldRangeMetres,
      localRangeMetres,
    });
  }
  entries.sort((a, b) => a.sourceOsmWayId - b.sourceOsmWayId || SIDE_ORDER.get(a.side) - SIDE_ORDER.get(b.side) || a.worldRangeMetres[0] - b.worldRangeMetres[0] || a.worldRangeMetres[1] - b.worldRangeMetres[1]);
  return entries;
}

function sourceIdsFromGlb(glb, tileId) {
  const primitives = glb.meshes?.[0]?.primitives;
  assert(Array.isArray(primitives) && primitives.length, `${tileId} GLB has no mesh primitives`);
  const ids = new Set();
  for (const primitive of primitives) {
    assert(primitive.extras?.category, `${tileId} GLB primitive category missing`);
    if (primitive.extras.category !== 'buildings') continue;
    assert(Array.isArray(primitive.extras.sourceOsmWayIds), `${tileId} building primitive source IDs missing`);
    let previous = -Infinity;
    for (const id of primitive.extras.sourceOsmWayIds) {
      assert(Number.isSafeInteger(id) && id >= 0, `${tileId} GLB building source ID is not a safe integer`);
      assert(id >= previous, `${tileId} GLB building source IDs are not sorted`);
      previous = id;
      ids.add(id);
    }
  }
  return [...ids].sort((a, b) => a - b);
}

function tilePairKey(leftId, rightId) { return `${leftId}|${rightId}`; }

function neighbor(descriptor, direction, byGrid) {
  const [x, y] = descriptor.gridIndex;
  const delta = direction === 'east' ? [1, 0] : [0, 1];
  return byGrid.get(`${x + delta[0]}/${y + delta[1]}`) ?? null;
}

function intersection(left, right) {
  const rightSet = new Set(right);
  return left.filter((id) => rightSet.has(id));
}

function mapById(entries) {
  const map = new Map();
  for (const entry of entries) {
    const list = map.get(entry.sourceOsmWayId) ?? [];
    list.push(entry);
    map.set(entry.sourceOsmWayId, list);
  }
  for (const [id, list] of map) map.set(id, list.sort((a, b) => a.worldRangeMetres[0] - b.worldRangeMetres[0] || a.worldRangeMetres[1] - b.worldRangeMetres[1]));
  return map;
}

function comparableEntry(entry) {
  return {
    sourceOsmWayId: entry.sourceOsmWayId,
    sourceGeometryHash: entry.sourceGeometryHash,
    worldEndpointsEpsg26910Metres: entry.worldEndpointsEpsg26910Metres,
    worldRangeMetres: entry.worldRangeMetres,
    localRangeMetres: entry.localRangeMetres,
  };
}

function sideEntriesFor(entries, side) {
  return entries.filter((entry) => entry.side === side).sort((a, b) => a.sourceOsmWayId - b.sourceOsmWayId || a.worldRangeMetres[0] - b.worldRangeMetres[0] || a.worldRangeMetres[1] - b.worldRangeMetres[1]);
}

function exactEntryArrays(left, right) {
  // Adjacent tiles traverse the same source boundary in opposite directions;
  // compare the canonical world-axis intervals, not the winding of each
  // clipped ring's endpoint pair.
  const normalized = (entries) => entries.map((entry) => entry.worldRangeMetres);
  return JSON.stringify(normalized(left)) === JSON.stringify(normalized(right));
}

function graphClosure(startId, edges) {
  const adjacency = new Map();
  const add = (left, right) => {
    const list = adjacency.get(left) ?? []; list.push(right); adjacency.set(left, list);
  };
  for (const edge of edges) if (edge.exactSharedSourceOsmWayIds.length) {
    add(edge.leftTileId, edge.rightTileId);
    add(edge.rightTileId, edge.leftTileId);
  }
  const visited = new Set([startId]); const queue = [startId];
  while (queue.length) for (const next of adjacency.get(queue.shift()) ?? []) if (!visited.has(next)) { visited.add(next); queue.push(next); }
  return [...visited].sort();
}

async function readManifest() {
  const manifestBytes = await readFile(MANIFEST_PATH);
  const manifest = JSON.parse(manifestBytes);
  assert.equal(manifest.kind, 'sf-metric-tile-set', 'Production manifest kind drifted');
  assert(Array.isArray(manifest.tiles) && manifest.tiles.length > 0, 'Production manifest has no tiles');
  const descriptors = manifest.tiles.map((descriptor) => ({ descriptor, tile: tileIdentity(descriptor) }));
  const byGrid = new Map(descriptors.map(({ descriptor, tile }) => [`${tile.gridEasting}/${tile.gridNorthing}`, descriptor]));
  assert(byGrid.has('1441/10893'), 'Ferry tile is absent from production manifest');
  return { manifest, manifestBytes, descriptors, byGrid, manifestSha256: `sha256:${sha256(manifestBytes)}` };
}

async function readGlbInventory(descriptors) {
  const sourceIdsByTile = new Map();
  const inventory = [];
  for (const descriptor of descriptors) {
    assertSha256(descriptor.lod0?.sha256, `${descriptor.id} manifest GLB hash`);
    const glbPath = path.join(ROOT, descriptor.lod0.path);
    const bytes = await readFile(glbPath);
    assert.equal(`sha256:${sha256(bytes)}`, descriptor.lod0.sha256, `${descriptor.id} GLB bytes do not match manifest`);
    const glb = parseGlbJson(bytes, descriptor.id);
    const sourceIds = sourceIdsFromGlb(glb, descriptor.id);
    sourceIdsByTile.set(descriptor.id, sourceIds);
    inventory.push({ id: descriptor.id, gridIndex: descriptor.gridIndex, sha256: descriptor.lod0.sha256, bytes: bytes.length, buildingSourceOsmWayIds: sourceIds });
    assertSha256(descriptor.receipt?.sha256, `${descriptor.id} manifest receipt hash`);
    const receiptBytes = await readFile(path.join(ROOT, descriptor.receipt.path));
    assert.equal(`sha256:${sha256(receiptBytes)}`, descriptor.receipt.sha256, `${descriptor.id} receipt bytes do not match manifest`);
  }
  inventory.sort((a, b) => a.id.localeCompare(b.id));
  return { sourceIdsByTile, inventory, inventorySha256: `sha256:${sha256(jsonBytes(inventory))}` };
}

function conservativeEdges(descriptors, byGrid, sourceIdsByTile) {
  const edges = [];
  for (const descriptor of descriptors) for (const direction of ['east', 'north']) {
    const other = neighbor(descriptor, direction, byGrid);
    if (!other) continue;
    const shared = intersection(sourceIdsByTile.get(descriptor.id) ?? [], sourceIdsByTile.get(other.id) ?? []);
    if (!shared.length) continue;
    edges.push({
      leftTileId: descriptor.id,
      rightTileId: other.id,
      direction,
      sharedSourceOsmWayIds: shared,
    });
  }
  edges.sort((a, b) => a.leftTileId.localeCompare(b.leftTileId) || a.rightTileId.localeCompare(b.rightTileId));
  return edges;
}

function tileIdsInSet(descriptors, ids) {
  const wanted = new Set(ids);
  return descriptors.filter(({ descriptor }) => wanted.has(descriptor.id));
}

async function computeLedger() {
  const { manifest, manifestBytes, descriptors, byGrid, manifestSha256 } = await readManifest();
  const glbInventory = await readGlbInventory(manifest.tiles);
  const conservative = conservativeEdges(manifest.tiles, byGrid, glbInventory.sourceIdsByTile);
  const conservativeClosure = graphClosure(FERRY_TILE_ID, conservative.map((edge) => ({ ...edge, exactSharedSourceOsmWayIds: edge.sharedSourceOsmWayIds })));
  const candidateIds = new Set(conservativeClosure);
  const conservativeInternal = conservative.filter((edge) => candidateIds.has(edge.leftTileId) && candidateIds.has(edge.rightTileId));
  const ledgerTileIds = new Set(conservativeClosure);
  for (const descriptor of manifest.tiles) if (candidateIds.has(descriptor.id)) for (const direction of ['east', 'north']) {
    const other = neighbor(descriptor, direction, byGrid); if (other) ledgerTileIds.add(other.id);
  }

  const shared = await loadSfMetricSharedInputs();
  assert.equal(shared.pbfHash.sha256, 'dda3821dd92f8d8bf34abe503ac81f20a439ee02a210a9d68d2c7c5d66fb0cae', 'OSM PBF hash drifted');
  const featuresById = new Map(shared.osmFeatureCache.filter((feature) => feature.tags?.building).map((feature) => [feature.id, feature]));
  const descriptorsById = new Map(manifest.tiles.map((descriptor) => [descriptor.id, descriptor]));
  const tileById = new Map(manifest.tiles.map((descriptor) => [descriptor.id, tileIdentity(descriptor)]));
  const sideLedger = [];
  const edgeEntries = new Map();
  const unmapped = [];
  for (const tileId of [...ledgerTileIds].sort()) {
    const descriptor = descriptorsById.get(tileId);
    const tile = tileById.get(tileId);
    const entries = [];
    for (const sourceOsmWayId of glbInventory.sourceIdsByTile.get(tileId) ?? []) {
      const feature = featuresById.get(sourceOsmWayId);
      if (!feature) { unmapped.push({ tileId, sourceOsmWayId, reason: 'building-way-missing-from-byte-locked-PBF' }); continue; }
      assert.equal(feature.refs[0], feature.refs.at(-1), `${tileId} emitted building way ${sourceOsmWayId} is not closed`);
      const clipped = dedupeRing(clipPolygon(feature.en.slice(0, -1), tile));
      if (clipped.length < 3) { unmapped.push({ tileId, sourceOsmWayId, reason: 'GLB-source-ID-has-no-three-vertex-clipped-ring' }); continue; }
      entries.push(...buildingBoundaryEntries(feature, tile));
    }
    entries.sort((a, b) => a.sourceOsmWayId - b.sourceOsmWayId || SIDE_ORDER.get(a.side) - SIDE_ORDER.get(b.side) || a.worldRangeMetres[0] - b.worldRangeMetres[0] || a.worldRangeMetres[1] - b.worldRangeMetres[1]);
    for (const side of SIDES) {
      const sideEntriesValue = sideEntriesFor(entries, side).map(comparableEntry);
      if (sideEntriesValue.length) sideLedger.push({ tileId, side, entries: sideEntriesValue });
      edgeEntries.set(`${tileId}|${side}`, sideEntriesFor(entries, side));
    }
    // The descriptor is intentionally touched so a future manifest shape
    // change cannot silently bypass the tile identity checks above.
    assert(descriptor?.lod0?.path, `${tileId} manifest descriptor missing GLB path`);
  }
  assert.equal(unmapped.length, 0, `Unable to map ${unmapped.length} emitted building IDs back to closed clipped source ways`);

  const sideByTile = (tileId, side) => edgeEntries.get(`${tileId}|${side}`) ?? [];
  const exactEdges = [];
  const conservativeEdgeReports = [];
  for (const edge of conservative) {
    if (!candidateIds.has(edge.leftTileId)) continue;
    const leftSide = edge.direction === 'east' ? 'east' : 'north';
    const rightSide = edge.direction === 'east' ? 'west' : 'south';
    const leftById = mapById(sideByTile(edge.leftTileId, leftSide));
    const rightById = mapById(sideByTile(edge.rightTileId, rightSide));
    const exactSharedSourceOsmWayIds = [];
    const falsePositiveSourceOsmWayIds = [];
    const mismatchedSourceOsmWayIds = [];
    for (const sourceOsmWayId of edge.sharedSourceOsmWayIds) {
      const leftEntries = leftById.get(sourceOsmWayId) ?? [];
      const rightEntries = rightById.get(sourceOsmWayId) ?? [];
      if (!leftEntries.length && !rightEntries.length) {
        falsePositiveSourceOsmWayIds.push(sourceOsmWayId);
        continue;
      }
      if (!leftEntries.length || !rightEntries.length || !exactEntryArrays(leftEntries, rightEntries)) {
        mismatchedSourceOsmWayIds.push(sourceOsmWayId);
        continue;
      }
      exactSharedSourceOsmWayIds.push(sourceOsmWayId);
    }
    const report = {
      leftTileId: edge.leftTileId,
      rightTileId: edge.rightTileId,
      direction: edge.direction,
      sharedSourceOsmWayIds: edge.sharedSourceOsmWayIds,
      exactSharedSourceOsmWayIds,
      falsePositiveSourceOsmWayIds,
      mismatchedSourceOsmWayIds,
      exact: exactSharedSourceOsmWayIds.length > 0,
    };
    conservativeEdgeReports.push(report);
    if (report.exact) exactEdges.push(report);
  }
  conservativeEdgeReports.sort((a, b) => a.leftTileId.localeCompare(b.leftTileId) || a.rightTileId.localeCompare(b.rightTileId));
  exactEdges.sort((a, b) => a.leftTileId.localeCompare(b.leftTileId) || a.rightTileId.localeCompare(b.rightTileId));
  sideLedger.sort((a, b) => a.tileId.localeCompare(b.tileId) || SIDE_ORDER.get(a.side) - SIDE_ORDER.get(b.side));
  const exactClosure = graphClosure(FERRY_TILE_ID, conservativeEdgeReports);

  const ledger = {
    schemaVersion: 1,
    kind: 'sf-building-seam-edge-ledger',
    status: 'preview-source-lock-evidence-only',
    promotion: { runtime: false, productionManifest: false, gameplay: false, verticalCertification: false },
    tileGrid: {
      crs: 'EPSG:26910',
      tileSizeMetres: TILE_SIZE_METRES,
      units: 'metres',
      quantization: `JavaScript Math.round(value*1e${QUANTIZATION_DECIMALS})/1e${QUANTIZATION_DECIMALS}, matching the production builder`,
      clipper: 'Sutherland-Hodgman half-open source ring clip matching build-ferry-production-tile-v1',
      runtimeScaleClaim: 1,
    },
    source: {
      osmPbf: { path: 'public/data/sf/SanFrancisco.osm.pbf', bytes: shared.pbfHash.bytes, sha256: `sha256:${shared.pbfHash.sha256}` },
      geometryLock: { path: 'public/data/world/source-locks/sf-ferry-osm-horizontal-geometry-v1.lock.json', bytes: shared.geometryAuthBytes.length, sha256: `sha256:${sha256(shared.geometryAuthBytes)}` },
      horizontalLock: { path: 'public/data/world/source-locks/sf-ferry-3dep-2023-horizontal-crs-v1.lock.json', bytes: shared.horizontalLockBytes.length, sha256: `sha256:${sha256(shared.horizontalLockBytes)}` },
      sourceGeometryHash: 'sha256:stable-json-over-way-tags-nodeIds-and-q6-lonlat-v1',
    },
    inputs: {
      manifest: { path: relative(MANIFEST_PATH), bytes: manifestBytes.length, sha256: manifestSha256 },
      productionGlbInventory: { tileCount: glbInventory.inventory.length, sha256: glbInventory.inventorySha256 },
    },
    conservativeSourceIdClosure: {
      ferryTileId: FERRY_TILE_ID,
      tileIds: conservativeClosure,
      tileCount: conservativeClosure.length,
      adjacencyEdgeCount: conservativeInternal.length,
      allManifestAdjacencyEdgeCount: conservative.length,
      adjacencyEdges: conservativeInternal,
    },
    exactClippedBoundaryClosure: {
      ferryTileId: FERRY_TILE_ID,
      tileIds: exactClosure,
      tileCount: exactClosure.length,
      adjacencyEdgeCount: exactEdges.length,
      adjacencyEdges: exactEdges,
    },
    edgeComparison: {
      comparedConservativeEdges: conservativeEdgeReports.length,
      exactEdges: exactEdges.length,
      falsePositiveSourceIdWays: conservativeEdgeReports.reduce((sum, edge) => sum + edge.falsePositiveSourceOsmWayIds.length, 0),
      mismatchedSourceIdWays: conservativeEdgeReports.reduce((sum, edge) => sum + edge.mismatchedSourceOsmWayIds.length, 0),
      reports: conservativeEdgeReports,
    },
    sourceWayBoundaryLedger: sideLedger,
    assertions: {
      everyManifestGlbHashMatches: true,
      everyManifestReceiptHashMatches: true,
      everyGlbBuildingSourceIdMapsToClosedPbfWay: true,
      everyBoundaryEndpointIsExactEpsg26910MetreCoordinate: true,
      adjacentExactRangesEqualAfterQ6: true,
      exactClosureIsSubsetOfConservativeClosure: exactClosure.every((tileId) => candidateIds.has(tileId)),
      verticalAccuracyClaim: 'not provided; horizontal seam evidence only',
    },
  };
  assert.equal(ledger.assertions.exactClosureIsSubsetOfConservativeClosure, true);
  const ledgerBytes = jsonBytes(ledger);
  const compressedLedgerBytes = gzipSync(ledgerBytes, { level: 9, mtime: 0 });
  return { ledger, receipt: {
    schemaVersion: 1,
    kind: 'sf-building-seam-edge-ledger-receipt',
    status: 'preview-source-lock-evidence-only',
    nonPromotion: 'This receipt is not a runtime input, production manifest authorization, gameplay input, or vertical accuracy claim.',
    artifact: {
      ledgerPath: relative(LEDGER_PATH),
      compression: 'gzip-level-9-mtime-0',
      compressedBytes: compressedLedgerBytes.length,
      compressedSha256: `sha256:${sha256(compressedLedgerBytes)}`,
      uncompressedBytes: ledgerBytes.length,
      uncompressedSha256: `sha256:${sha256(ledgerBytes)}`,
    },
    source: ledger.source,
    inputs: ledger.inputs,
    ferry: {
      tileId: FERRY_TILE_ID,
      conservativeSourceIdClosureTileCount: ledger.conservativeSourceIdClosure.tileCount,
      exactClippedBoundaryClosureTileCount: ledger.exactClippedBoundaryClosure.tileCount,
      conservativeAdjacencyEdgeCount: ledger.conservativeSourceIdClosure.adjacencyEdgeCount,
      allManifestAdjacencyEdgeCount: ledger.conservativeSourceIdClosure.allManifestAdjacencyEdgeCount,
      exactAdjacencyEdgeCount: ledger.exactClippedBoundaryClosure.adjacencyEdgeCount,
      falsePositiveSourceIdWays: ledger.edgeComparison.falsePositiveSourceIdWays,
      mismatchedSourceIdWays: ledger.edgeComparison.mismatchedSourceIdWays,
      exactClosureTileIdsSha256: `sha256:${sha256(jsonBytes(ledger.exactClippedBoundaryClosure.tileIds))}`,
    },
    counts: {
      manifestTiles: manifest.tiles.length,
      conservativeClosureTiles: ledger.conservativeSourceIdClosure.tileCount,
      exactClosureTiles: ledger.exactClippedBoundaryClosure.tileCount,
      conservativeEdgesCompared: ledger.edgeComparison.comparedConservativeEdges,
      exactEdges: ledger.edgeComparison.exactEdges,
      sourceWayBoundaryRecords: sideLedger.reduce((sum, side) => sum + side.entries.length, 0),
    },
    claims: {
      horizontalCrs: 'EPSG:26910',
      oneRuntimeUnitPerMetre: true,
      exactBoundaryCoordinateQuantizationMetres: 1e-6,
      verticalSourceAccuracy: 'unrealized/source-declared; this artifact makes no vertical accuracy claim',
    },
  }, glbInventory };
}

async function verifyOrWrite() {
  const { ledger, receipt } = await computeLedger();
  const ledgerBytes = jsonBytes(ledger);
  const compressedLedgerBytes = gzipSync(ledgerBytes, { level: 9, mtime: 0 });
  const receiptBytes = jsonBytes(receipt);
  assert.equal(receipt.artifact.compressedBytes, compressedLedgerBytes.length);
  assert.equal(receipt.artifact.compressedSha256, `sha256:${sha256(compressedLedgerBytes)}`);
  assert.equal(receipt.artifact.uncompressedBytes, ledgerBytes.length);
  assert.equal(receipt.artifact.uncompressedSha256, `sha256:${sha256(ledgerBytes)}`);
  const write = process.argv.includes('--write');
  if (write) {
    await mkdir(path.dirname(LEDGER_PATH), { recursive: true });
    await writeFile(LEDGER_PATH, compressedLedgerBytes);
    await writeFile(RECEIPT_PATH, receiptBytes);
  } else {
    const [committedCompressedLedgerBytes, committedReceiptBytes] = await Promise.all([readFile(LEDGER_PATH), readFile(RECEIPT_PATH)]);
    assert.equal(Buffer.compare(committedCompressedLedgerBytes, compressedLedgerBytes), 0, 'Checked-in compressed seam ledger bytes drifted; rerun with --write only after source review');
    assert.equal(Buffer.compare(gunzipSync(committedCompressedLedgerBytes), ledgerBytes), 0, 'Checked-in seam ledger payload does not decode to the verified canonical JSON');
    assert.equal(Buffer.compare(committedReceiptBytes, receiptBytes), 0, 'Checked-in seam ledger receipt bytes drifted; rerun with --write only after source review');
    assert.equal(JSON.parse(committedReceiptBytes).artifact.compressedSha256, receipt.artifact.compressedSha256, 'Checked-in seam ledger receipt digest drifted');
  }
  process.stdout.write(`${JSON.stringify({
    result: write ? 'SF building seam-edge ledger written and verified' : 'SF building seam-edge ledger verified',
    status: receipt.status,
    ferryTileId: FERRY_TILE_ID,
    manifestTiles: receipt.counts.manifestTiles,
    conservativeClosureTiles: receipt.ferry.conservativeSourceIdClosureTileCount,
    exactClosureTiles: receipt.ferry.exactClippedBoundaryClosureTileCount,
    conservativeEdgesCompared: receipt.ferry.conservativeAdjacencyEdgeCount,
    allManifestAdjacencyEdges: receipt.ferry.allManifestAdjacencyEdgeCount,
    exactEdges: receipt.ferry.exactAdjacencyEdgeCount,
    falsePositiveSourceIdWays: receipt.ferry.falsePositiveSourceIdWays,
    mismatchedSourceIdWays: receipt.ferry.mismatchedSourceIdWays,
    sourceWayBoundaryRecords: receipt.counts.sourceWayBoundaryRecords,
    ledgerCompressedSha256: receipt.artifact.compressedSha256,
    ledgerUncompressedSha256: receipt.artifact.uncompressedSha256,
    receiptPath: relative(RECEIPT_PATH),
    ledgerPath: relative(LEDGER_PATH),
  }, null, 2)}\n`);
}

await verifyOrWrite();
